    def encode(self, view):
        result = []
        for c in view['carts']:
            at = self.index[c['at']]
            loc = at if c['to'] is None else self.transit[at, self.index[c['to']], c['remaining']]
            result.append(loc * 3 + c['stage'])
        return tuple(result)

