                return INF
            if world == -1:
                end = max(self.tables[w][i][tick][loc * 2 + stage] for w in (0, 1))
            else:
                end = self.tables[world][i][tick][loc * 2 + stage]
            if end == INF:
                return INF
            total += end - tick
        return total

    def successors(self, state, tick, world):
        if tick >= self.horizon:
            return
