    deferred = []
    batch = 400
    candidates = 0
    prefix_done = False
    while time.monotonic() < w.stop:
        if not prefix_done:
            status, result = prefix.run(2000)
            if status == 'solved':
                return result[1], None
            if status == 'branch':
                (tick, state), shared = result
                deferred.append([tick, state, shared, [None, None], [None, None]])
                candidates += 1
            elif status in ('impossible', 'large'):
                prefix_done = True
