        # continuation cannot prevent considering a different early dispatch.
        if deferred:
            item = deferred.pop(0)
            tick, state, shared, plans, searches = item
            possible = True
            for world in (0, 1):
                if plans[world] is not None:
                    continue
                if searches[world] is None:
                    searches[world] = Search(w, state, tick, world)
                status, result = searches[world].run(batch)
                if status == 'solved':
                    plans[world] = result[1]
                    searches[world] = None
                elif status in ('impossible', 'large'):
                    possible = False
